mapper.select:
/* 요금제/부가서비스/안심보험 등의 카테고리 조회 */
SELECT A.CTG_CD, A.CTG_NM, A.CTG_BAS_DESC FROM MSF_RATE_ADSVC_CTG_BAS A , ( SELECT CTG_CD, COUNT(1) AS PROD_ID_COUNT FROM MSF_RATE_ADSVC_CTG_PROD_REL WHERE USE_YN='Y' AND PSTNG_START_DATE < TO_CHAR(NOW(), 'YYYYMMDDHH24MISS') AND PSTNG_END_DATE >= TO_CHAR(NOW(), 'YYYYMMDDHH24MISS') GROUP BY CTG_CD ) B WHERE 1=1
AND A.RATE_ADSVC_DIV_CD = #{prodCtgTypeCd}
AND A.CTG_CD = B.CTG_CD AND B.PROD_ID_COUNT > 0
AND A.USE_YN = 'Y' AND PSTNG_START_DATE < TO_CHAR(NOW(), 'YYYYMMDDHH24MISS') AND PSTNG_END_DATE >= TO_CHAR(NOW(), 'YYYYMMDDHH24MISS') ORDER BY A.SORT_ODRG

/* 요금제/부가서비스/안심보험 등의 카테고리 상세 조회 */ SELECT PROD_ID, CTG_CD, COALESCE(SORT_ODRG, 0) SORT_ODRG FROM MSF_RATE_ADSVC_CTG_PROD_REL WHERE 1=1 AND CTG_CD in ( SELECT CTG_CD FROM MSF_RATE_ADSVC_CTG_BAS A WHERE 1=1
AND A.RATE_ADSVC_DIV_CD = #{prodCtgTypeCd}
AND A.CTG_CD = #{prodCtgId}
AND A.USE_YN = 'Y' AND PSTNG_START_DATE < TO_CHAR(NOW(), 'YYYYMMDDHH24MISS') AND PSTNG_END_DATE >= TO_CHAR(NOW(), 'YYYYMMDDHH24MISS') ) AND USE_YN = 'Y' AND PSTNG_START_DATE < TO_CHAR(NOW(), 'YYYYMMDDHH24MISS') AND PSTNG_END_DATE >= TO_CHAR(NOW(), 'YYYYMMDDHH24MISS')
AND PROD_ID IN (SELECT DTL_CD FROM MSF_CD_DTL WHERE CD_GROUP_ID = 'SVCCHG_RATE_CD' AND USE_YN = 'Y' AND TO_CHAR(NOW(),'yyyymmddhh24miss') BETWEEN PSTNG_START_DATE AND PSTNG_END_DATE )
ORDER BY SORT_ODRG

/* 요금제/부가서비스/안심보험 등의 카테고리 상세 조회 */ SELECT DISTINCT B.PROD_ID FROM MSF_RATE_ADSVC_CTG_PROD_REL B WHERE 1=1 AND CTG_CD in ( SELECT CTG_CD FROM MSF_RATE_ADSVC_CTG_BAS A WHERE 1=1
AND A.RATE_ADSVC_DIV_CD = #{prodCtgTypeCd}
AND A.CTG_CD = #{prodCtgId}
AND A.USE_YN = 'Y' AND PSTNG_START_DATE < TO_CHAR(NOW(), 'YYYYMMDDHH24MISS') AND PSTNG_END_DATE >= TO_CHAR(NOW(), 'YYYYMMDDHH24MISS') ) AND USE_YN = 'Y' AND PSTNG_START_DATE < TO_CHAR(NOW(), 'YYYYMMDDHH24MISS') AND PSTNG_END_DATE >= TO_CHAR(NOW(), 'YYYYMMDDHH24MISS')
AND PROD_ID IN (SELECT DTL_CD FROM MSF_CD_DTL WHERE CD_GROUP_ID = 'SVCCHG_RATE_CD' AND USE_YN = 'Y' AND TO_CHAR(NOW(),'yyyymmddhh24miss') BETWEEN PSTNG_START_DATE AND PSTNG_END_DATE )

/* 매장 재고 조회(목록) - 상품아이디(휴대폰 목록을 조회할 때 매장 재고조회해서 상품아이디를 가지고 M전산 조회 진행함) */ SELECT PROD_ID FROM MSF_PROD_STOR_INVENTORY_TXN WHERE 1=1 AND USE_YN = 'Y' AND USE_STTUS_CD = 'N' AND (BIZ_NO IS NULL OR BIZ_NO = '') AND AGENT_CD = #{agentCd}
AND PROD_ID = #{prodId}
AND PSTNG_START_DATE < TO_CHAR(NOW(), 'YYYYMMDDHH24MISS') AND PSTNG_END_DATE >= TO_CHAR(NOW(), 'YYYYMMDDHH24MISS') GROUP BY PROD_ID

/* 매장 재고 조회 - Count */
SELECT count(1)
FROM MSF_PROD_STOR_INVENTORY_TXN
WHERE 1=1
  AND USE_YN = 'Y'
  AND USE_STTUS_CD = 'N'
  AND (BIZ_NO IS NULL OR BIZ_NO = '')
  AND AGENT_CD = #{agentCd}
  AND PROD_SN = #{prodSn}

    AND PROD_ID = #{prodId}

  AND PSTNG_START_DATE < TO_CHAR(NOW(), 'YYYYMMDDHH24MISS')
  AND PSTNG_END_DATE >= TO_CHAR(NOW(), 'YYYYMMDDHH24MISS')

/* 카테고리별 상품목록 조회 (2026.06.20) */ SELECT CTG_CD FROM MSF_RATE_ADSVC_CTG_PROD_REL WHERE USE_YN='Y' AND PSTNG_START_DATE <= TO_CHAR(NOW(), 'YYYYMMDD'||'000000') AND PSTNG_END_DATE >= TO_CHAR(NOW(), 'YYYYMMDD'||'000000') AND CTG_CD IN (SELECT CTG_CD FROM MSF_RATE_ADSVC_CTG_BAS WHERE RATE_ADSVC_DIV_CD = #{rateAdsvcDivCd} )
AND PROD_ID IN
#{product}
GROUP BY CTG_CD

/* 유효한 상품목록으로 조회한 카테고리 (코드/코드명) 목록 조회 (2026.06.20) */
      SELECT CTG_CD, CTG_NM
      FROM MSF_RATE_ADSVC_CTG_BAS
      WHERE USE_YN = 'Y'
        AND RATE_ADSVC_DIV_CD = #{rateAdsvcDivCd}
        AND PSTNG_START_DATE <= TO_CHAR(NOW(), 'YYYYMMDD'||'000000')
        AND PSTNG_END_DATE >= TO_CHAR(NOW(), 'YYYYMMDD'||'000000')

        AND CTG_CD IN

             #{ctgCd}


      ORDER BY SORT_ODRG
